// Types generated by hand from the backend OpenAPI spec (/v3/api-docs).
// Field names match the backend EXACTLY. Do not rename them.

export type ISODate = string; // "YYYY-MM-DD"

export type AdminType = 'DOCTOR' | 'MANAGER' | 'SYSADMIN';
export type CampaignStatus = 'PENDING' | 'APPROVED' | 'REJECTED';
export type AppointmentStatus = 'BOOKED' | 'CANCELLED' | 'COMPLETE';
export type RequestStatus = 'PENDING' | 'EXPIRED' | 'APPROVED' | 'REJECTED' | 'COMPLETE';
export type InventoryStatus = 'AVAILABLE' | 'EXPIRED' | 'SHIPPED';

/* ---------- Entities (responses) ---------- */

export interface Admin {
  id: number;
  username: string;
  phoneNum: string;
  type: AdminType;
}

export interface Hoster {
  id: number;
  username: string;
  orgName: string;
  phoneNum: string;
}

export interface Donor {
  id: number;
  username: string;
  // The backend keeps the underscore spelling on these two.
  f_Name: string;
  l_Name: string;
  nic: string;
  bloodType: string;
  dob: ISODate;
  phoneNum: string;
}

/** The four kinds of account, as /auth/delete/user and /auth/get/user expect them. */
export type UserType = 'DONOR' | 'HOSTER' | 'HOSPITAL' | 'ADMIN';

/**
 * The signed-in account, from /auth/get/me. The endpoint returns whichever user type the token
 * belongs to, so everything past the shared fields depends on the role. Email is deliberately
 * absent: it lives on the auth record and the backend does not serialise it here.
 */
export interface Me {
  id: number;
  username: string;
  email: string;
  phoneNum: string;
  f_Name?: string;
  l_Name?: string;
  nic?: string;
  bloodType?: string;
  dob?: ISODate;
  orgName?: string;
  hospitalName?: string;
  address?: string;
  type?: AdminType;
}

export interface Hospital {
  id: number;
  username: string;
  hospitalName: string;
  address: string;
  phoneNum: string;
}

export interface Bank {
  bankID: number;
  name: string;
  address: string;
  manager: Admin | null;
}

export interface Venue {
  venueID: number;
  name: string;
  address: string;
  assignedBank: number; // Bank.bankID
}

export interface Campaign {
  campID: number;
  name: string;
  startDate: ISODate;
  endDate: ISODate;
  status: CampaignStatus;
  hoster: Hoster;
  venueSet: Venue[];
}

/** Raw appointment as the backend sends it. */
export interface AppointmentResponseRaw {
  appID: number;
  date: ISODate;
  status: AppointmentStatus;
  donor: {
    donorID: number;
    fName: string;
    lName: string;
    bloodType: string;
    phoneNum: string;
  };
  campaign: { campID: number; name: string; startDate: ISODate; endDate: ISODate };
  venue: { venueID: number; name: string; address: string };
}

/** Clean appointment used by the UI (see mapAppointment in api/appointments.ts). */
export interface Appointment {
  appID: number;
  date: ISODate;
  status: AppointmentStatus;
  donor: { donorID: number; firstName: string; lastName: string; bloodType: string; phone: string };
  campaign: { campID: number; name: string; startDate: ISODate; endDate: ISODate };
  venue: { venueID: number; name: string; address: string };
}

export interface BloodRequest {
  reqID: number;
  /** One quantity per blood type, in the order of BLOOD_TYPES (utils/constants.ts). */
  quantities: number[];
  deadline: ISODate;
  status: RequestStatus;
  hospitalID: number;
  hospitalName: string;
}

export interface InventoryItem {
  itemID: number;
  bloodType: string;
  dateCollected: ISODate;
  expiry: ISODate;
  status: InventoryStatus;
  appointment: number; // appID
  bank: number; // bankID
}

/* ---------- Auth ---------- */

export interface LoginRequest {
  username: string;
  password: string;
}

export interface TokenResponse {
  token: string;
  role: string;
  adminType?: AdminType | null;
  userID?: number;
  success: boolean;
  error?: string | null;
}

export interface DonorCreate {
  f_Name: string;
  l_Name: string;
  nic: string;
  bloodType: string;
  dob: ISODate;
  email: string;
  phoneNum: string;
  username: string;
  password: string;
}

export interface HosterCreate {
  orgName: string;
  email: string;
  phoneNum: string;
  username: string;
  password: string;
}

export interface HospitalCreate {
  hospitalName: string;
  address: string;
  email: string;
  phoneNum: string;
  username: string;
  password: string;
}

export interface AdminCreate {
  email: string;
  phoneNum: string;
  username: string;
  password: string;
  type: AdminType;
}

/* ---------- Account edits ----------
   Every field is optional: the backend applies only the ones that arrive non-empty and leaves the
   rest alone, so an omitted password means "keep the current password". */

export interface UserUpdate {
  id: number;
  email?: string;
  phoneNum?: string;
  username?: string;
  password?: string;
}

export interface DonorUpdate extends UserUpdate {
  f_Name?: string;
  l_Name?: string;
  nic?: string;
  bloodType?: string;
  dob?: ISODate;
}

export interface HosterUpdate extends UserUpdate {
  orgName?: string;
}

export interface HospitalUpdate extends UserUpdate {
  hospitalName?: string;
  address?: string;
}

/* ---------- Request bodies ---------- */

export interface CampaignCreate {
  name: string;
  startDate: ISODate;
  endDate: ISODate;
  hosterID: number;
  venueIDs: number[];
}

export interface CampaignUpdate extends Partial<CampaignCreate> {
  status?: CampaignStatus;
}

export interface AppointmentCreate {
  date: ISODate;
  campId: number; // note lowercase "d" in the backend
  donorID: number;
  venueID: number;
}

export interface AppointmentUpdate extends Partial<AppointmentCreate> {
  status?: AppointmentStatus;
}

export interface VenueCreate {
  name: string;
  address: string;
  bankID: number;
}

export interface VenueUpdate extends VenueCreate {
  venueID: number;
}

export interface BankCreate {
  name: string;
  address: string;
  managerID: number;
}

export interface RequestCreate {
  quantities: number[];
  deadline: ISODate;
}

export interface RequestUpdate extends RequestCreate {
  reqID: number;
  hospitalID: number;
}

export interface InventoryCreate {
  bloodType: string;
  appointmentID: number;
  bankID: number;
}

export interface InventoryStatusUpdate {
  itemID: number;
  status: InventoryStatus;
}
